import { MakeLogicType, kea, path, connect, listeners } from 'kea'

import { newAccountMenuLogic } from 'lib/components/Account/newAccountMenuLogic'
import { helpMenuLogic } from 'lib/components/HelpMenu/helpMenuLogic'

import { todayShellLogic } from './todayShellLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHelpMenuRedirectLogicValues {
    phoneLayout: boolean // todayShellLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHelpMenuRedirectLogicActions {
    setHelpMenuOpen: (isOpen: boolean) => {
        isOpen: boolean
    } // helpMenuLogic
    toggleHelpMenu: () => {
        value: true
    } // helpMenuLogic
    setAccountMenuOpen: (isOpen: boolean) => {
        isOpen: boolean
    } // newAccountMenuLogic
    toggleAccountMenu: () => {
        value: true
    } // newAccountMenuLogic
}

export type todayHelpMenuRedirectLogicType = MakeLogicType<
    todayHelpMenuRedirectLogicValues,
    todayHelpMenuRedirectLogicActions
>

/**
 * On the rail the account menu holds what the help menu held, so whatever opens the help menu opens the account menu
 * instead: the `?` shortcut toggles it, and the nav switch sets it. The phone layout keeps the help menu as its More
 * sheet. The account menu mounts this, so `helpMenuLogic` and its health summary load only where the rail shows, never
 * on a shared page that mounts the shell logic.
 */
export const todayHelpMenuRedirectLogic = kea<todayHelpMenuRedirectLogicType>([
    path(['layout', 'today', 'todayHelpMenuRedirectLogic']),
    connect(() => ({
        values: [todayShellLogic, ['phoneLayout']],
        actions: [
            helpMenuLogic,
            ['setHelpMenuOpen', 'toggleHelpMenu'],
            newAccountMenuLogic,
            ['setAccountMenuOpen', 'toggleAccountMenu'],
        ],
    })),
    listeners(({ actions, values }) => ({
        setHelpMenuOpen: ({ isOpen }) => {
            if (isOpen && !values.phoneLayout) {
                actions.setHelpMenuOpen(false)
                actions.setAccountMenuOpen(true)
            }
        },
        toggleHelpMenu: () => {
            if (!values.phoneLayout) {
                actions.setHelpMenuOpen(false)
                actions.toggleAccountMenu()
            }
        },
    })),
])
